{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "생물의 서식 공간을 만들고 시민의 생태학습을 돕는 공원의 유형",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "해당 공원은 생태공원입니다. 서울특별시 도시공원 조례 제3조제1호는 생태공원을 ‘생물서식공간의 조성으로 생물다양성의 증진과 더불어 시민의 휴식ㆍ생태학습을 목적으로 설치하는 공원’으로 정하고 있습니다.",
          "b_ids": "도시공원:제3조제1호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "집 근처 가로변에서 휴식과 경관 개선을 위한 공원의 유형",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "해당 공원은 가로공원입니다. 서울특별시 도시공원 조례 제3조제3호는 가로공원을 ‘가로변 또는 주거지 인근에 설치하여 시민의 휴식과 경관의 개선을 목적으로 하는 공원’으로 정하고 있습니다.",
          "b_ids": "도시공원:제3조제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
